import{_ as o,E as n,b as s,d as t,i as e,J as r,k as i,aS as a,a as d}from"./chunks/framework.M2Whok06.js";const p="/assets/google-ad-01.Ba2A9Siw.png",h="/assets/google-ad-03.BQKjLR7d.png",c="/assets/google-ad-04.NG_dWnXp.png",G=JSON.parse('{"title":"06-谷歌Adsense税务信息填报","description":"","frontmatter":{},"headers":[],"relativePath":"note/stationmaster/seo/06-谷歌Adsense税务信息填报.md","filePath":"note/stationmaster/seo/06-谷歌Adsense税务信息填报.md","lastUpdated":1748870674000}'),g={name:"note/stationmaster/seo/06-谷歌Adsense税务信息填报.md"},_=a('<h1 id="_06-谷歌adsense税务信息填报" tabindex="-1">06-谷歌Adsense税务信息填报 <a class="header-anchor" href="#_06-谷歌adsense税务信息填报" aria-label="Permalink to &quot;06-谷歌Adsense税务信息填报&quot;">​</a></h1><p>参考：<a href="https://freechao.com/6280.html" target="_blank" rel="noreferrer">https://freechao.com/6280.html</a></p><p><a href="https://youngjuning.js.org/66ec8687cd46/" target="_blank" rel="noreferrer">https://youngjuning.js.org/66ec8687cd46/</a></p><p>付款方式：<a href="https://youngjuning.js.org/5de90b19f4d9/" target="_blank" rel="noreferrer">https://youngjuning.js.org/5de90b19f4d9/</a></p><h2 id="新加坡税务填写" tabindex="-1">新加坡税务填写 <a class="header-anchor" href="#新加坡税务填写" aria-label="Permalink to &quot;新加坡税务填写&quot;">​</a></h2><p>当我们的ad收入达到$100之后，就需要事先填写一些必要的信息来为了到时候确保谷歌给我们正常打款，其中3个最重要的信息是就是。</p><ol><li>pin码验证身份信息</li><li>填写银行卡收款信息</li><li>填写税务信息</li></ol><p>有的小伙伴是需要填写美国的税务信息，有的是新加坡的，而我的是新加坡的，具体我们依照谷歌ad后台给的提示走。</p><p><img src="'+p+'" alt=""></p><p>对于利用Google系产品进行创收的小伙伴，一定会收到Google Adsense要求进行新加坡税务信息的填写， 而在以前，Google仅要求提供美国的税务信息填写，这个也非常好理解，Google是美国的企业，我们在谷歌上赚钱， 填写美国的税务信息申报也属实正常，那么为什么Google会要求我们额外填写新加坡税务信息呢？</p><p>因为你通过Google进行创收，购买需要税务信息的Google服务，而且谷歌亚太地区的款项都是从谷歌新加坡公司打款出来的， 所以你这边需要向新加坡的税务机构提交你的税务信息， 一方面是避免重复征收，其次是如果不填写的话，会对你征收最高规格的税务，同时对你的账号造成影响。</p><div class="tip custom-block github-alert"><p class="custom-block-title">新加坡非居民个人所得税2024为：24%，也就是说如果你挣$1000，那么需要交$240的税。还是非常的高的，那么有办法不交么？答案是可以的。</p><p>那就是需要证明你已经在中国交过税了。那么就需要你去税务局申请一个【中国税收居民身份证明】的文件。</p></div><p><strong>开始填写：</strong> <br><br> 公司信息：</p><ul><li>您的业务类型是什么？ 个人/独资经营者 <br></li><li>您在新加坡是否有常设机构？否 <br></li><li>您是否根据海外供应商注册制度注册了新加坡商品及服务税 (GST)？ 否 <br></li><li>唯一实体编号（可选） 不填 <br><br> 免税：</li><li>您是否有资格申请免税待遇？ 是</li></ul><p>税务居住地：</p>',15),f=t("li",null,"国家？中国",-1),m=t("li",null,"税务居住地证明：单据类型",-1),u=a('<h3 id="查看自己的谷歌账号签约的哪家谷歌公司主体" tabindex="-1">查看自己的谷歌账号签约的哪家谷歌公司主体 <a class="header-anchor" href="#查看自己的谷歌账号签约的哪家谷歌公司主体" aria-label="Permalink to &quot;查看自己的谷歌账号签约的哪家谷歌公司主体&quot;">​</a></h3><p>登录谷歌ad后台，菜单下面，找到隐私条款，查看。 <img src="'+h+'" alt=""></p><p>谷歌在全球一共有4家公司</p><table tabindex="0"><thead><tr><th style="text-align:left;">主体英文名</th><th style="text-align:left;">主体中文名</th><th style="text-align:left;">税号</th><th style="text-align:left;">缔约国名称</th></tr></thead><tbody><tr><td style="text-align:left;">Google LLC</td><td style="text-align:left;">谷歌有限公司</td><td style="text-align:left;">EU372000041</td><td style="text-align:left;">美国</td></tr><tr><td style="text-align:left;">Google Ireland</td><td style="text-align:left;">谷歌爱尔兰有限公司</td><td style="text-align:left;">IE6388047V</td><td style="text-align:left;">爱尔兰</td></tr><tr><td style="text-align:left;">Google Advertising (Shanghai) Company Limited</td><td style="text-align:left;">谷歌广告（上海）有限公司</td><td style="text-align:left;">913100006901563863</td><td style="text-align:left;">中国</td></tr><tr><td style="text-align:left;">Google Asia Pacific Pte. Ltd.</td><td style="text-align:left;">谷歌亚太私人有限公司</td><td style="text-align:left;">200817984R</td><td style="text-align:left;">新加坡</td></tr></tbody></table><h3 id="adsense在线服务条款" tabindex="-1">AdSense在线服务条款 <a class="header-anchor" href="#adsense在线服务条款" aria-label="Permalink to &quot;AdSense在线服务条款&quot;">​</a></h3><p>中文：<a href="https://www.google.com/adsense/new/localized-terms?rc=CN&amp;ce=1&amp;hl=zh_CN" target="_blank" rel="noreferrer">https://www.google.com/adsense/new/localized-terms?rc=CN&amp;ce=1&amp;hl=zh_CN</a></p><p>英文版：<a href="https://www.google.com/adsense/new/localized-terms?rc=CN" target="_blank" rel="noreferrer">https://www.google.com/adsense/new/localized-terms?rc=CN</a></p><h3 id="需要的文件" tabindex="-1">需要的文件 <a class="header-anchor" href="#需要的文件" aria-label="Permalink to &quot;需要的文件&quot;">​</a></h3><p>《中国税收居民身份证明申请表》.docx： <a href="https://wwd.lanzout.com/iTlGA2iv43yd" target="_blank" rel="noreferrer">https://wwd.lanzout.com/iTlGA2iv43yd</a></p><p>AdSense 在线服务条款.pdf： <a href="https://wwd.lanzout.com/iBVsw2iv43ze" target="_blank" rel="noreferrer">https://wwd.lanzout.com/iBVsw2iv43ze</a></p><h3 id="中国税收居民身份证明的两种申请方法" tabindex="-1">中国税收居民身份证明的两种申请方法 <a class="header-anchor" href="#中国税收居民身份证明的两种申请方法" aria-label="Permalink to &quot;中国税收居民身份证明的两种申请方法&quot;">​</a></h3><p>国家税务总局-12366 纳税服务平台 <a href="https://12366.chinatax.gov.cn/bsfw/onlinetaxation/main" target="_blank" rel="noreferrer">https://12366.chinatax.gov.cn/bsfw/onlinetaxation/main</a></p><p>1）线下申请</p><p>打开税务总局网站链：<a href="https://www.gov.cn/zhengce/zhengceku/2019-11/05/content_5448919.htm" target="_blank" rel="noreferrer">https://www.gov.cn/zhengce/zhengceku/2019-11/05/content_5448919.htm</a></p><p>网站界面下拉到最下面有两份附件，一份是《中国税收居民身份证明》，第二份是《中国税收居民身份证明申请表》，下载填写之后，提交到你附近的税务部门申请盖章确认，不过这个方法比较费时间和精力，因为需要你来回跑。</p><p>基本信息：</p><ul><li>纳税人识别号：就是你的身份证号</li><li>主管税务机关名称：需要登录《个人所得税》APP上面看，找到任意一个纳税明细就能看到</li></ul><p>谷歌新加坡税务相关信息：</p><ul><li>缔约对方国家（地区）：新加坡共和国</li><li>对方纳税人识别号：200817984R</li><li>对方纳税人名称（英文）：Google Asia Pacific Pte. Ltd.</li><li>对方纳税人名称（英文）：谷歌亚太私人有限公司</li><li>拟享受协定名称一：中华人民共和国政府和新加坡共和国政府关于对所得避免双重征税和防止偷漏税的协定</li><li>金额随便写</li></ul><p>《中国税收居民身份证明》申请表具体填写样式 <img src="'+c+'" alt=""></p><p>2）线上申请</p><p>我看其他人都是用的线上申请，但是现在入口貌似找不到，界面都不一样。所以我感觉个人的话，这条路应该走不通了。</p>',22);function b(x,w,y,A,k,P){const l=n("font");return d(),s("div",null,[_,t("ul",null,[f,m,t("li",null,[e("上传 ："),r(l,{color:"red"},{default:i(()=>[e("需要去申请,下面是申请的2种方法")]),_:1})])]),u])}const T=o(g,[["render",b]]);export{G as __pageData,T as default};
